def find_holes(grid, shape_color, bg_color):
    """Find holes (bg_color regions) completely surrounded by shape_color"""
    rows = len(grid)
    cols = len(grid[0])

    # For each bg region, check if it's surrounded by shape
    holes = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == bg_color:
                # Do flood fill to check if region is closed
                stack = [(r, c)]
                region = [(r, c)]
                visited = {(r, c)}

                while stack:
                    cr, cc = stack.pop()
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if (nr, nc) not in visited and grid[nr][nc] == bg_color:
                                visited.add((nr, nc))
                                stack.append((nr, nc))
                                region.append((nr, nc))

                # Check if any neighbor of this region is shape
                has_shape_neighbor = False
                for rr, rc in region:
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = rr + dr, rc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == shape_color:
                            has_shape_neighbor = True
                            break
                    if has_shape_neighbor:
                        break

                if has_shape_neighbor:
                    holes.append((region, has_shape_neighbor))

    return holes

